css:
/* Korean Engine Specialist - Checkout | Korean Engine Specialist (/checkout/) */
*{margin:0;padding:0;box-sizing:border-box}
:root{
 --ink:#070a0e; --ink2:#0d1319; --char:#121c25; --char2:#18242e; --char3:#1f2f3b;
 --blue:#0a63f5; --blue-l:#4f94ff; --blue-d:#0a3fb0;
 --red:#e21019; --red-l:#ff2a31; --red-d:#a80a11;
 --paper:#f4f7f9; --paper2:#e9eef2; --white:#fff;
 --tx:#15202a; --tx2:#55646f; --line:#e1e8ed; --line-d:#243440;
 --gut:clamp(18px,5vw,56px); --rad:14px; --maxw:1280px; --utilh:44px;
 --sh:0 14px 36px -16px rgba(9,15,20,.26); --sh2:0 34px 78px -30px rgba(9,15,20,.55);
 --fd:'Archivo',system-ui,sans-serif; --fb:'Inter',system-ui,sans-serif;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--fb);color:var(--tx);background:var(--ink);line-height:1.6;overflow-x:hidden}
svg{width:18px;height:18px;flex-shrink:0}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
p{overflow-wrap:anywhere}
select option{background:#0d1319;color:#fff}
.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut);width:100%}
.eyb{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;font-size:12.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--red);background:rgba(226,16,25,.09);border:1px solid rgba(226,16,25,.26);padding:8px 16px 8px 12px;border-radius:999px}
.eyb::before{content:"";width:9px;height:9px;background:var(--red);border-radius:2px;transform:rotate(45deg);animation:pip 2.2s ease-in-out infinite}
@keyframes pip{0%,100%{transform:rotate(45deg) scale(1);opacity:1}50%{transform:rotate(45deg) scale(.55);opacity:.5}}
.dark .eyb,.inkbg .eyb{color:var(--red-l);background:rgba(255,42,49,.12);border-color:rgba(255,42,49,.34)}
.dark .eyb::before,.inkbg .eyb::before{background:var(--red-l)}
.btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;border-radius:10px;padding:16px 28px;font-size:15px;letter-spacing:.03em;cursor:pointer;transition:.22s;border:0;white-space:nowrap;position:relative;overflow:hidden;text-transform:uppercase}
.btn svg{width:17px;height:17px}
.btn::after{content:"";position:absolute;top:0;left:-130%;width:55%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.4),transparent);transform:skewX(-18deg);transition:left .65s ease}
.btn:hover::after{left:170%}
.btn-r{background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;box-shadow:0 16px 32px -12px rgba(226,16,25,.75)}
.btn-r:hover{transform:translateY(-3px);box-shadow:0 22px 44px -12px rgba(226,16,25,.9)}
.kes-header,.kes-footer,.kes-page{margin:0}
.sec{padding-top:clamp(58px,7vw,96px);padding-bottom:clamp(58px,7vw,96px)}
.sec.alt{background:var(--paper)}
.sec.dark{background:var(--char);color:#eaf2f6}
.sec.inkbg{background:var(--ink);color:#eaf2f6;position:relative;overflow:hidden}
.shead{max-width:64ch}
.shead.ctr{margin:0 auto;text-align:center}
.sec h2{font-size:clamp(27px,3.9vw,44px);text-transform:uppercase;color:var(--ink);margin-top:16px}
.sec.dark h2,.sec.inkbg h2{color:#fff}
.shead .sub{color:var(--tx2);font-size:clamp(15px,1.5vw,17px);margin-top:14px}
.sec.dark .sub,.sec.inkbg .sub{color:#a9b9c3}
@property --q1{syntax:'<integer>';initial-value:0;inherits:false}
@property --q2{syntax:'<integer>';initial-value:0;inherits:false}
@property --q3{syntax:'<integer>';initial-value:0;inherits:false}
@property --q4{syntax:'<integer>';initial-value:0;inherits:false}
@media(max-width:720px){
.eyb{font-size:11px;letter-spacing:.13em;padding:7px 14px 7px 11px}
}
@media(max-width:560px){
.btn{white-space:normal;text-align:center;line-height:1.25;padding:15px 20px;justify-content:center}
.ab-cta>.btn,.hero-cta>.btn,.cta-btns>.btn{flex:1 1 100%}
.pbeat .btn{white-space:normal}
}
@media (prefers-reduced-motion:reduce){
*{scroll-behavior:auto!important}
.rv,.grad,.blob,.pbeat::before,.sq-tab-ar,.sq-tab-ic::after,.hvis-rt,.hero-bg,.spin-r,.ab-gear,.sq-head-ic svg,.eyb::before,.ab-ph .ph-ic,.btn::after{animation:none!important}
}
:root{--steel:#1b2631;--steel2:#243240;--steel3:#2d3e4d;--bolt:#8ea2b2}
.eyb::before{border-radius:50%;transform:none;box-shadow:0 0 0 3px rgba(226,16,25,.22);animation:pip 2.6s ease-in-out infinite}
.btn-r{border-top:1px solid rgba(255,255,255,.3);border-bottom:1px solid rgba(0,0,0,.35)}
@media(max-width:720px){
.pstrip .btn{width:100%;justify-content:center}
}
html{background:var(--ink)}
.kes-page{background:var(--white)}
.btn-ghd{background:#fff;color:var(--tx2);border:1.5px solid var(--line);box-shadow:none}
.btn-ghd:hover{background:#f3f7fa;border-color:#c6d2db;color:var(--ink);transform:translateY(-2px)}
.sc-line{display:grid;grid-template-columns:62px 1fr 26px;gap:13px;align-items:start;background:#fff;border:1px solid var(--line);border-radius:13px;padding:13px;margin-bottom:11px}
.sc-line img,.sc-noimg{width:62px;height:52px;object-fit:cover;border-radius:9px;border:1px solid var(--line);background:var(--paper2)}
.sc-l-t{min-width:0}
.sc-l-t{display:flex;flex-direction:column;gap:3px}
.sc-l-n{font-family:var(--fd);font-weight:800;font-size:14px;line-height:1.3;color:var(--ink)}
.sc-l-v{color:var(--tx2);font-size:12.4px;line-height:1.4}
.sc-l-b{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:9px}
.sc-l-p{font-family:var(--fd);font-weight:900;font-size:15px;color:var(--ink)}
.sc-qty{display:inline-flex;align-items:center;border:1.5px solid var(--line);border-radius:9px;overflow:hidden;background:#fff}
.sc-q{width:28px;height:30px;border:0;background:none;font-family:var(--fd);font-weight:900;font-size:15px;color:var(--tx2);cursor:pointer;transition:.16s;line-height:1}
.sc-q:hover{background:var(--paper2);color:var(--ink)}
.sc-qn{min-width:28px;text-align:center;font-family:var(--fd);font-weight:900;font-size:13.5px;color:var(--ink);border-left:1.5px solid var(--line);border-right:1.5px solid var(--line);height:30px;display:inline-flex;align-items:center;justify-content:center}
.sc-x{width:26px;height:26px;border:0;background:none;color:var(--tx2);cursor:pointer;border-radius:7px;display:grid;place-items:center;transition:.16s}
.sc-x:hover{background:rgba(226,16,25,.1);color:var(--red)}
.sc-x svg{width:14px;height:14px}
.crumb{font-size:13px;color:#8fa2b0;font-weight:600;margin-bottom:20px}
.crumb a{color:#cfdae2}
.crumb a:hover{color:var(--red-l)}
.crumb span{margin:0 7px;opacity:.5}
.crumb b{color:#fff;font-weight:700}
.epr-card .btn{margin-top:8px}
.crumb .crumb-x{font-style:normal;color:#8fa2b0;opacity:.75;cursor:default}
.opts{display:grid;gap:10px;margin-bottom:20px}
.opt{display:flex;align-items:center;gap:12px;padding:14px 16px;cursor:pointer;border:1.5px solid var(--line);border-radius:12px;background:#fff;transition:.18s}
.opt:hover{border-color:var(--blue-l)}
.opt input{position:absolute;opacity:0;pointer-events:none}
.opt .dot{flex:0 0 auto;width:18px;height:18px;border-radius:50%;border:2px solid var(--line);position:relative;transition:.18s}
.opt:has(:checked){border-color:var(--red);background:rgba(226,16,25,.045);box-shadow:0 0 0 3px rgba(226,16,25,.1)}
.opt:has(:checked) .dot{border-color:var(--red)}
.opt:has(:checked) .dot::after{content:"";position:absolute;inset:3px;border-radius:50%;background:var(--red)}
.opt-t{flex:1 1 auto;min-width:0}
.opt-t b{font-family:var(--fd);font-weight:800;font-size:14.6px;color:var(--ink);display:block}
.opt-t s{display:block;font-size:13px;color:var(--tx2);text-decoration:none;margin-top:3px}
.shop{display:grid;grid-template-columns:minmax(0,1.95fr) minmax(286px,.75fr);gap:clamp(18px,2.1vw,30px);align-items:start}
@media(max-width:1050px){
.shop{grid-template-columns:1fr}
}
.ct-h,.ln{display:grid;grid-template-columns:var(--ct-cols);gap:clamp(12px,1.2vw,18px);align-items:center}
.ln{padding:clamp(16px,1.8vw,22px) clamp(16px,1.6vw,20px);border-bottom:1px solid var(--line);transition:background .18s}
.ln:last-child{border-bottom:0}
.ln:hover{background:#fbfcfd}
.ln-p{display:flex;gap:clamp(13px,1.5vw,18px);align-items:center;min-width:0}
.ln-p img{width:104px;height:84px;object-fit:cover;border-radius:12px;flex:0 0 auto;border:1px solid var(--line);background:var(--paper)}
.ln-t{min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:5px}
.ln-name{font-family:var(--fd);font-weight:800;font-size:16px;line-height:1.3;color:var(--ink)}
.ln-var{font-size:13.6px;color:var(--tx2);line-height:1.4}
.ln-badge{display:inline-block;margin-top:2px;padding:4px 10px;border-radius:999px;background:rgba(10,99,245,.08);color:var(--blue-d);font-family:var(--fd);font-weight:700;font-size:12px;line-height:1.45}
.ln-q{display:flex;justify-content:center}
.ln-a{display:flex;flex-direction:column;align-items:center;gap:3px;text-align:center}
.ln-tot{font-family:var(--fd);font-weight:900;font-size:20px;color:var(--ink);letter-spacing:-.01em}
.ln-each{font-size:12.2px;color:var(--tx2)}
.ln-x{display:flex;justify-content:flex-end}
.ln-x button{width:38px;height:38px;display:flex;align-items:center;justify-content:center;border:1.5px solid var(--line);border-radius:10px;cursor:pointer;color:var(--tx2);background:#fff;transition:.18s}
.ln-x button:hover{border-color:var(--red);color:var(--red);background:rgba(226,16,25,.07)}
.ln-x svg{width:16px;height:16px;stroke-width:2.2}
.ct-lbl{display:none;font-family:var(--fd);font-weight:800;font-size:10.4px;letter-spacing:.13em;text-transform:uppercase;color:var(--tx2)}
@media(max-width:820px){
.ln{grid-template-columns:1fr auto;gap:16px 18px;padding:18px}
.ln-p{grid-column:1/-1}
.ln-q,.ln-a{align-items:flex-start;justify-content:flex-start;text-align:left}
.ln-a{grid-column:2;align-items:flex-end;text-align:right}
.ln{position:relative;padding-top:20px}
.ln-x{position:absolute;top:12px;right:12px}
.ln-x button{width:32px;height:32px;border-color:transparent;background:transparent}
.ln-p{padding-right:34px}
.ct-lbl{display:block;margin-bottom:6px}
}
@media(max-width:420px){
.ln-p img{width:76px;height:62px}
}
.sum{background:#fff;border:1px solid var(--line);border-radius:18px;padding:clamp(22px,2.4vw,30px);box-shadow:var(--sh);position:sticky;top:24px}
@media(max-width:1050px){
.sum{position:static}
}
.sum h2{font-family:var(--fd);font-weight:900;font-size:19px;color:var(--ink);padding-bottom:16px;border-bottom:1px solid var(--line)}
.sum-r{display:flex;justify-content:space-between;gap:16px;padding:11px 0;font-size:14.8px;color:var(--tx2)}
.sum-r b{color:var(--ink);font-weight:700}
.sum-r.big{border-top:1px solid var(--line);margin-top:8px;padding-top:16px}
.sum-r.big span{font-family:var(--fd);font-weight:800;font-size:15px;color:var(--ink);text-transform:uppercase;letter-spacing:.09em}
.sum-r.big b{font-family:var(--fd);font-weight:900;font-size:clamp(25px,2.8vw,31px);line-height:1}
.sum-btn{width:100%;justify-content:center;margin-top:16px}
.sum-note{display:flex;gap:10px;margin-top:16px;padding-top:16px;border-top:1px solid var(--line);color:var(--tx2);font-size:13.1px;line-height:1.55}
.sum-note svg{flex:0 0 auto;width:16px;height:16px;stroke:var(--blue);margin-top:2px}
.ck-items{display:grid;gap:15px;padding-bottom:16px;border-bottom:1px solid var(--line);margin-bottom:6px}
.ck-it{display:flex;gap:13px;align-items:center}
.ck-it img{width:56px;height:46px;object-fit:cover;border-radius:8px;flex:0 0 auto;border:1px solid var(--line);background:var(--paper)}
.ck-it div{min-width:0;flex:1;display:flex;flex-direction:column;gap:3px}
.ck-n{font-family:var(--fd);font-weight:800;font-size:13.8px;color:var(--ink);line-height:1.3}
.ck-v{color:var(--tx2);font-size:12.4px;line-height:1.4}
.ck-p{font-family:var(--fd);font-weight:900;font-size:15px;color:var(--ink);flex:0 0 auto}
.fset{background:#fff;border:1px solid var(--line);border-radius:18px;padding:clamp(22px,2.5vw,32px);box-shadow:var(--sh);margin-bottom:clamp(18px,2vw,26px)}
.fset-h{display:flex;align-items:center;gap:13px;margin-bottom:20px}
.fset-n{flex:0 0 auto;width:32px;height:32px;border-radius:9px;display:flex;align-items:center;justify-content:center;background:var(--ink);color:#fff;font-family:var(--fd);font-weight:900;font-size:14.5px}
.fset-h h2{font-family:var(--fd);font-weight:900;font-size:clamp(19px,2.1vw,23px);color:var(--ink)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
@media(max-width:620px){
.grid2{grid-template-columns:1fr}
}
.fld{min-width:0}
.fld-f{grid-column:1/-1}
.fld label{display:block;font-family:var(--fd);font-weight:700;font-size:13px;color:var(--tx);margin-bottom:6px}
.fld label i{color:var(--red);font-style:normal}
.fld input,.fld select{min-width:0;width:100%;font:inherit;font-size:15px;padding:13px 14px;border:1.5px solid var(--line);border-radius:10px;background:#fff;color:var(--tx);appearance:none}
.fld input:focus,.fld select:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px rgba(226,16,25,.14)}
.hint{color:var(--tx2);font-size:12.8px;margin-top:6px;line-height:1.55}
.panel{display:none;margin-top:16px;padding-top:18px;border-top:1px dashed var(--line)}
.fset:has(#d-ship:checked) .p-ship,.fset:has(#d-pick:checked) .p-pick{display:block}
.payout{display:flex;gap:15px;align-items:flex-start;background:var(--paper);border:1px solid var(--line);border-radius:13px;padding:18px 20px}
.payout-ic{flex:0 0 auto;width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:rgba(10,99,245,.1)}
.payout-ic svg{width:19px;height:19px;stroke:var(--blue-d);stroke-width:2.4}
.payout b{display:block;font-family:var(--fd);font-weight:800;font-size:15px;color:var(--ink)}
.payout p{color:var(--tx2);font-size:13.8px;line-height:1.55;margin-top:5px}
.payout-cards{display:inline-block;margin-top:10px;font-size:12.8px;font-weight:600;color:var(--tx2);letter-spacing:.02em}
.ck-err{display:flex;align-items:center;gap:9px;margin-bottom:14px;padding:13px 16px;border-radius:11px;background:rgba(226,16,25,.08);border:1px solid rgba(226,16,25,.3);color:var(--red-d);font-size:14px;font-weight:600}
.ck-err[hidden]{display:none}
.orx-box{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:18px 20px;display:grid;gap:11px;margin-bottom:24px}
.orx-r{display:flex;justify-content:space-between;gap:18px;font-size:14.6px;color:var(--tx2);align-items:baseline}
.orx-r small{color:var(--tx2);font-size:12.6px}
.orx-r b{color:var(--ink);font-family:var(--fd);font-weight:800;white-space:nowrap}
.orx-tot{border-top:1px solid var(--line);padding-top:12px;margin-top:2px}
.orx-tot span{font-family:var(--fd);font-weight:800;color:var(--ink)}
.orx-tot b{font-size:21px;font-weight:900}
.orx{background:#fff;border:1px solid var(--line);border-radius:18px;padding:clamp(26px,3.4vw,46px);box-shadow:var(--sh);max-width:720px;margin:0 auto}
.orx-ic{width:62px;height:62px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(10,99,245,.1);margin:0 auto 20px}
.orx-ic svg{width:30px;height:30px;stroke:var(--blue);stroke-width:2.6}
.orx h2{font-family:var(--fd);font-weight:900;font-size:clamp(24px,3.2vw,34px);text-align:center;color:var(--ink);letter-spacing:-.02em}
.orx .lead{text-align:center;color:var(--tx2);margin:12px auto 26px;max-width:52ch}
.orx-next{display:grid;gap:12px;margin-bottom:26px}
.orx-next div{display:flex;gap:12px;align-items:flex-start;font-size:14.6px;color:var(--tx2);line-height:1.6}
.orx-next svg{flex:0 0 auto;width:18px;height:18px;stroke:var(--red);stroke-width:2.6;margin-top:3px}
.orx-act{display:flex;flex-wrap:wrap;gap:12px;justify-content:center}
.placedbox{display:none}
.crumb-ink a{color:var(--tx2)}
.crumb-ink a:hover{color:var(--red)}
.crumb-ink span{color:var(--line)}
.crumb-ink b{color:var(--ink)}

.placedbox{display:block}
.orx-box[hidden],.orx-none[hidden]{display:none}
.orx-r b{white-space:normal;text-align:right}
.orx-tot b{white-space:nowrap}
.orx h1{font-family:var(--fd);font-weight:900;font-size:clamp(24px,3.2vw,34px);text-align:center;color:var(--ink);letter-spacing:-.02em}
.orx-none{text-align:center;color:var(--tx2);font-size:14.6px;line-height:1.65;background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:24px}
.orx-none a{color:var(--red);font-weight:700}
